import type { ToastLocalContextType } from "../toast.types";

import { createContext, useContext } from "react";

export const ToastLocalContext = createContext<ToastLocalContextType | null>(null);

export const useToastContext = () => {
  const context = useContext(ToastLocalContext);
  if (!context) {
    throw new Error("Toast compound components cannot be rendered outside the Toast component");
  }
  return context;
};
